-- Preserve personal-contact deletion when a legacy member receives a permission snapshot.
UPDATE access_profiles SET permissions=array_append(permissions,'contacts.delete') WHERE system_role='member' AND NOT ('contacts.delete'=ANY(permissions));
CREATE OR REPLACE FUNCTION seed_system_access_profiles() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 INSERT INTO access_profiles(tenant_id,name,description,permissions,system_role) VALUES (NEW.id,'Proprietário','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','contacts.delete','chat','calendar','reminders','schedules','reports','users.view','users.invite','users.manage','profiles.manage','audit.view','audit.content','mailboxes.manage','company.manage','integrations','signatures','labels','rules','archives']::text[],'owner'),
(NEW.id,'Administrador','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','contacts.delete','chat','calendar','reminders','schedules','reports','users.view','users.invite','users.manage','profiles.manage','audit.view','audit.content','mailboxes.manage','company.manage','integrations','signatures','labels','rules','archives']::text[],'admin'),
(NEW.id,'Supervisor','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','chat','calendar','reminders','schedules','reports','integrations','signatures','labels','rules','users.view','audit.view','contacts.delete']::text[],'supervisor'),
(NEW.id,'Membro','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','chat','calendar','reminders','schedules','reports','integrations','signatures','labels','rules','contacts.delete']::text[],'member') ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;
